// Editorial source: supplied FEATURES.md, plugin 0.1.1 manifests and implementation.
export const arabic={};
export function P(en,ar){arabic[en]=ar;return en;}
const section=(id,title,arTitle,paragraphs=[],steps=[],note=null,code=null)=>({id,title:P(title,arTitle),paragraphs:paragraphs.map(([en,ar])=>P(en,ar)),steps:steps.map(([en,ar])=>P(en,ar)),note:note?P(...note):null,code});
const guide=(id,group,title,arTitle,summary,arSummary,sections,related=[])=>({id,group,title:P(title,arTitle),summary:P(summary,arSummary),sections,related});
export const groups={start:P('Get started','ابدأ هنا'),design:P('Build & design','البناء والتصميم'),site:P('Build a whole site','بناء موقع متكامل'),content:P('Content & reuse','المحتوى وإعادة الاستخدام'),forms:P('Forms & services','النماذج والخدمات'),shop:P('Your store','متجرك'),reference:P('Reference','المرجع'),help:P('Help & troubleshooting','المساعدة وحل المشكلات')};
export const guides=[
guide('installation','start','Install Zadex','تثبيت Zadex','Requirements, installation and the settings to check before your first page.','المتطلبات وخطوات التثبيت والإعدادات التي تحتاج مراجعتها قبل تصميم أول صفحة.',[
 section('requirements','Before you begin','قبل أن تبدأ',[[ 'Zadex requires WordPress 6.5 or later and PHP 8.0 or later. This documentation covers Zadex 0.1.1. All described builders and elements are included in the free plugin.','يتطلب Zadex إصدار WordPress 6.5 أو أحدث وPHP 8.0 أو أحدث. يغطي هذا التوثيق Zadex 0.1.1. جميع أدوات البناء والعناصر الموضحة متاحة في الإضافة المجانية.'],['You need a WordPress account allowed to install plugins. Editing access is controlled separately by WordPress permissions and Zadex Role Manager.','تحتاج حساب WordPress لديه صلاحية تثبيت الإضافات. وتخضع صلاحية التحرير لاحقًا لصلاحيات WordPress وإعدادات Role Manager في Zadex.']]),
 section('install','Install and activate','التثبيت والتفعيل',[],[['In WordPress, open Plugins → Add New Plugin and search for Zadex.','من لوحة WordPress، افتح إضافات ← أضف إضافة جديدة، ثم ابحث عن Zadex.'],['Install the Zadex plugin and activate it. If you already have an official plugin ZIP, use Upload Plugin instead, then activate it.','ثبّت إضافة Zadex ثم فعّلها. إذا كان لديك ملف ZIP الرسمي، استخدم رفع إضافة بدلًا من البحث، ثم فعّلها.'],['Open the Zadex settings page in the WordPress dashboard. Check that the content type you want to edit is enabled; posts and pages are enabled by default.','افتح إعدادات Zadex في لوحة التحكم. تأكد من تفعيل نوع المحتوى الذي تريد تحريره؛ المقالات والصفحات مفعّلة افتراضيًا.'],['Create or open a page and choose Edit with Zadex.','أنشئ صفحة أو افتح صفحة موجودة، ثم اختر Edit with Zadex.']]),
 section('check','Confirm the installation','التأكد من نجاح التثبيت',[[ 'The editor should open around the real page, with your theme visible. An empty page offers a column structure for its first section. If the edit button is missing, follow the editor-access troubleshooting guide.','يفتح المحرر حول الصفحة الحقيقية مع ظهور قالب موقعك. في الصفحة الفارغة يمكنك اختيار تخطيط أعمدة للقسم الأول. إذا لم يظهر زر التحرير، راجع دليل مشكلات الوصول إلى المحرر.']])
],['first-page','editor-access','theme-builder']),
guide('first-page','start','Build your first page','تصميم أول صفحة','Create a simple page, make it responsive and publish it deliberately.','أنشئ صفحة بسيطة، واضبطها للشاشات المختلفة، ثم انشرها بعد المعاينة.',[
 section('structure','Give the page a structure','أنشئ هيكل الصفحة',[],[['Open a page with Edit with Zadex. Use the + between sections or Add section at the end of the page.','افتح الصفحة باستخدام Edit with Zadex. اضغط + بين الأقسام أو Add section في نهاية الصفحة.'],['Choose a column structure. Start with one column for a heading, description and button, or use the starter section library.','اختر تخطيط الأعمدة. ابدأ بعمود واحد لعنوان ووصف وزر، أو استخدم قسمًا جاهزًا من مكتبة الأقسام.'],['Drag Heading, Text and Button into the container. Select each element to edit its content.','اسحب عناصر Heading وText وButton إلى الحاوية. حدّد كل عنصر لتعديل محتواه.']]),
 section('personalize','Make the content yours','خصّص المحتوى',[],[['Double-click supported text on the page to edit inline, or use the Content panel. Give the button a label and a destination.','انقر مرتين على النص المدعوم لتحريره مباشرةً، أو استخدم لوحة Content. اكتب نص الزر وحدّد وجهته.'],['Use Style for typography, colors and appearance. Use Advanced → Layout for spacing and sizing.','استخدم Style للخطوط والألوان والمظهر، وAdvanced ← Layout للمسافات والأبعاد.'],['Prefer a shared global color or font for repeated brand choices.','استخدم لونًا أو خطًا عامًا للاختيارات المتكررة في هوية موقعك.']]),
 section('publish','Preview and publish','المعاينة والنشر',[],[['Preview the desktop, tablet and mobile layouts. Adjust only the device values that need an override.','عاين التصميم على الكمبيوتر والتابلت والموبايل، وعدّل فقط القيم التي تحتاج تخصيصًا لذلك الجهاز.'],['Use Preview mode to inspect the page without editing tools. Check text, images and destinations.','استخدم وضع Preview لمعاينة الصفحة دون أدوات التحرير، وراجع النصوص والصور ووجهات الروابط.'],['Save the page. Choose a draft or published state intentionally, and confirm the save status before leaving. Open the public page to check the result.','احفظ الصفحة، واختر حالة المسودة أو النشر حسب المطلوب، وتأكد من حالة الحفظ قبل المغادرة. افتح الصفحة العامة لمراجعة النتيجة.']],['The website playground is an illustration. Actual editing, saving and publishing happen inside your WordPress installation.','مساحة التجربة في هذا الموقع توضيحية. التحرير والحفظ والنشر الفعلي تتم داخل موقع WordPress الخاص بك.'])
],['layout','responsive','saving']),
guide('editor','start','Find your way around the editor','التعرّف على المحرر','The canvas, element panels, Navigator and quick search.','الصفحة ولوحات العناصر ومتصفح العناصر والبحث السريع.',[
 section('canvas','The real page is the canvas','الصفحة الحقيقية هي مساحة العمل',[[ 'Zadex edits the real WordPress page inside your theme. Select an element on the canvas to show its controls. Its toolbar offers parent selection, moving, duplication, column splitting where applicable and deletion.','يحرّر Zadex صفحة WordPress الحقيقية داخل القالب. حدّد عنصرًا لإظهار إعداداته. يوفر شريطه اختيار العنصر الأب والنقل والتكرار وتقسيم الأعمدة عند توفره والحذف.'],['Right-click an element for copy, paste, style transfer, duplicate, delete, save as template and save as component actions. Actions can be restricted by a lock or your access mode.','انقر بزر الفأرة الأيمن على العنصر للنسخ واللصق ونقل التنسيق والتكرار والحذف والحفظ كقالب أو مكوّن. قد يمنع القفل أو مستوى صلاحيتك بعض هذه الإجراءات.']]),
 section('panels','Content, Style and Advanced','المحتوى والتنسيق والإعدادات المتقدمة',[[ 'Content changes what the element says or displays. Style changes its visual presentation. Advanced holds shared layout, positioning, responsive visibility, attributes, motion and display rules. The exact controls depend on the element.','تعدّل Content ما يعرضه العنصر، وتضبط Style مظهره، وتجمع Advanced إعدادات التخطيط والتموضع والظهور والأوصاف والحركة وشروط العرض. تختلف الأدوات التفصيلية باختلاف العنصر.']]),
 section('navigate','Navigate a long page','التنقل داخل صفحة طويلة',[],[['Open Navigator to inspect the element tree. Select the row for the element you need, including elements that are difficult to reach on the canvas.','افتح Navigator لرؤية شجرة العناصر. حدّد صف العنصر المطلوب، خاصةً إذا كان الوصول إليه على الصفحة صعبًا.'],['Rename rows to describe their purpose. Drag rows to reorder them; use hide and lock controls when organizing the design.','غيّر أسماء الصفوف لتوضيح وظيفتها، واسحبها لإعادة الترتيب، واستخدم الإخفاء والقفل أثناء تنظيم التصميم.'],['Use Ctrl+K, or Command+K on macOS, for quick search. The keyboard shortcuts guide lists other verified commands.','استخدم Ctrl+K، أو Command+K على macOS، لفتح البحث السريع. ستجد بقية الأوامر الموثقة في دليل الاختصارات.']])
],['shortcuts','layout','roles']),
guide('layout','design','Sections, containers & grids','الأقسام والحاويات والشبكات','Choose a structure and control space without rebuilding the content.','اختيار الهيكل وضبط المسافات دون إعادة إنشاء المحتوى.',[
 section('choose','Choose the right layout','اختر التخطيط المناسب',[[ 'A Container provides a Flexbox layout and can act as a section or a nested column. Grid provides explicit rows and columns. Tabs, Accordion, Toggle and Off-Canvas provide nested content areas with their own interaction.','توفر Container تخطيط Flexbox ويمكن استخدامها قسمًا أو عمودًا داخليًا. توفر Grid صفوفًا وأعمدة صريحة. وتمنحك Tabs وAccordion وToggle وOff-Canvas مساحات محتوى داخلية بتفاعل خاص لكل منها.']]),
 section('columns','Create and re-split columns','إنشاء الأعمدة وإعادة تقسيمها',[],[['Use the section + control to choose from 12 column structures, including unequal column ratios.','استخدم زر + الخاص بالقسم للاختيار من 12 تخطيطًا، تشمل أعمدة بنسب غير متساوية.'],['Drag elements between containers or arrange them in Navigator. Select the parent container when you need to edit the whole section.','اسحب العناصر بين الحاويات أو رتّبها في Navigator. حدّد الحاوية الأم عندما تريد تعديل القسم بالكامل.'],['Use the split action on an existing section to change its column structure while keeping its content. A single Undo restores that split operation.','استخدم إجراء التقسيم في قسم موجود لتغيير هيكل أعمدته مع الاحتفاظ بالمحتوى. يمكن التراجع عن عملية التقسيم بخطوة Undo واحدة.']]),
 section('space','Understand spacing','فهم المسافات',[[ 'Padding adds space inside an element. Margin adds space outside it. Gap sets spacing between children in the layout. Start by adjusting the container rather than adding many empty spacer elements.','تضيف Padding مسافة داخل العنصر، وMargin مسافة خارجه، بينما تضبط Gap المسافة بين العناصر الأبناء. ابدأ بتعديل الحاوية بدلًا من الإكثار من عناصر الفراغ.'],['Preview narrow devices after changing width, minimum height, column ratios or positioning. Fixed dimensions can be inappropriate on smaller screens.','عاين الأجهزة الضيقة بعد تغيير العرض أو الحد الأدنى للارتفاع أو نسب الأعمدة أو التموضع؛ فقد لا تناسب الأبعاد الثابتة الشاشات الصغيرة.']])
],['responsive','element-settings','elements']),
guide('element-settings','design','Style an element','تنسيق عنصر','Work with typography, positioning, visibility and safe attributes.','العمل مع الخطوط والتموضع والإظهار وخصائص العناصر الآمنة.',[
 section('style','Work from content to appearance','ابدأ بالمحتوى ثم المظهر',[],[['Select the element and finish its Content settings first. Controls can appear or disappear depending on other selections.','حدّد العنصر وأكمل إعدادات Content أولًا. قد تظهر بعض الأدوات أو تختفي بناءً على اختيارات أخرى.'],['In Style, choose typography, foreground and background colors, borders, shadows and the other controls provided for that element.','في Style، اضبط الخطوط وألوان النص والخلفيات والحدود والظلال وبقية الخيارات التي يوفرها العنصر.'],['Where a control supports hover or a device override, choose that state or device before editing its value.','إذا كان الإعداد يدعم hover أو قيمة مختلفة لجهاز معين، اختر الحالة أو الجهاز أولًا ثم عدّل القيمة.']]),
 section('advanced','Use shared Advanced settings','استخدم الإعدادات المتقدمة المشتركة',[[ 'Layout covers dimensions and spacing. Position controls placement and stacking. Responsive controls hide an element on selected devices. Motion and display conditions have dedicated guides.','تضبط Layout الأبعاد والمسافات، وتتحكم Position في الموضع والطبقات، وتتيح Responsive إخفاء العنصر على أجهزة محددة. توجد أدلة مستقلة للحركة وشروط العرض.'],['Attributes accepts an ID, CSS class names and supported attributes. Script-capable attributes are rejected. IDs should be meaningful and unique on the page.','تقبل Attributes معرّف ID وأسماء فئات CSS والخصائص المدعومة. تُرفض الخصائص القادرة على تشغيل سكربتات. اختر معرّفات واضحة وغير مكررة داخل الصفحة.']]),
 section('code','What custom code is supported?','ما الكود المخصص المدعوم؟',[[ 'Use the design controls for appearance. Zadex does not provide a custom CSS or JavaScript entry feature. The HTML element accepts permitted markup and removes unsafe scripting content; it is not a place to execute scripts.','استخدم أدوات التصميم لضبط المظهر. لا يوفر Zadex حقولًا لكتابة CSS أو JavaScript مخصص. يقبل عنصر HTML الوسوم المسموح بها ويزيل محتوى السكربتات غير الآمن؛ وليس مساحة لتشغيل سكربتات.']])
],['global-styles','motion','conditions']),
guide('responsive','design','Responsive design','التصميم المتجاوب','Understand the desktop base, inherited values and device-specific overrides.','فهم إعداد الكمبيوتر الأساسي والقيم الموروثة والتخصيص حسب الجهاز.',[
 section('devices','Enable the devices you need','فعّل الأجهزة المطلوبة',[[ 'Up to seven devices are available: mobile, large mobile, tablet, large tablet, laptop, desktop and widescreen. Manage enabled devices and widths in the Zadex dashboard settings.','تتوفر سبعة أجهزة كحد أقصى: الموبايل والموبايل الكبير والتابلت والتابلت الكبير واللابتوب والكمبيوتر والشاشة العريضة. اضبط تفعيل الأجهزة وعروضها من إعدادات Zadex في لوحة التحكم.'],['Desktop is the base. Smaller device breakpoints use max-width; widescreen uses min-width. Do not assume a preview label is an exact physical device size.','الكمبيوتر هو الإعداد الأساسي. تستخدم المقاسات الأصغر max-width، بينما تستخدم الشاشة العريضة min-width. اسم الجهاز في المعاينة لا يعني أنه مقاس جهاز فعلي محدد.']]),
 section('inherit','Set an override intentionally','تخصيص القيم بوضوح',[],[['Set your initial layout on desktop. Switch to another enabled device in the editor.','اضبط التخطيط الأساسي على الكمبيوتر، ثم اختر جهازًا آخر مفعّلًا داخل المحرر.'],['Inspect a responsive control. A faded inherited value comes from a broader applicable setting, rather than an explicit value on that device.','راجع إعدادًا يدعم التجاوب. تشير القيمة الموروثة الباهتة إلى أنها آتية من إعداد أوسع ينطبق على الجهاز، وليست قيمة مخصصة له.'],['Enter a device value only when needed. Remove the explicit override to return to inheritance, using the control’s reset capability where available.','أدخل قيمة خاصة بالجهاز عند الحاجة فقط. للعودة إلى التوريث، أزل القيمة المخصصة باستخدام إعادة الضبط حيث تتوفر.'],['Check typography, gaps, column flow and device visibility on every enabled layout. Then inspect the public page at different browser widths.','راجع الخطوط والمسافات واتجاه الأعمدة وظهور العناصر في كل مقاس مفعّل، ثم اختبر الصفحة العامة بعروض مختلفة للمتصفح.']])
],['layout','global-styles','troubleshooting']),
guide('global-styles','design','Global styles & classes','التنسيقات والفئات العامة','Create a consistent design system that can change in one place.','بناء نظام تصميم متناسق يمكن تحديثه من مكان واحد.',[
 section('tokens','Set shared colors, fonts and spacing','الألوان والخطوط والمسافات المشتركة',[],[['Open Site settings and define your Global colors, Global fonts and Spacing variables.','افتح Site settings وحدّد Global colors وGlobal fonts وSpacing variables.'],['Apply these shared choices in compatible element controls instead of entering a separate local value each time.','استخدم هذه الاختيارات العامة داخل إعدادات العناصر الداعمة بدلًا من إدخال قيمة محلية منفصلة في كل مرة.'],['Change a shared value and preview the elements using it. Local overrides can prevent a particular element from following the shared value.','غيّر قيمة عامة وعاين العناصر التي تستخدمها. قد تمنع القيم المحلية المخصصة عنصرًا معينًا من اتباع القيمة العامة.']]),
 section('classes','Reuse styles with Global classes','إعادة استخدام التنسيق بالفئات العامة',[[ 'A global class lets you maintain a reusable style and apply it to multiple elements. Class import and export support moving a style collection between projects. Use descriptive names so a teammate can recognize the purpose.','تتيح الفئة العامة حفظ تنسيق قابل لإعادة الاستخدام وتطبيقه على عدة عناصر. يمكنك استيراد الفئات وتصديرها لنقل مجموعة تنسيقات بين المشروعات. استخدم أسماء واضحة ليسهل على فريقك فهم وظيفة كل فئة.']]),
 section('theme-style','Define site defaults','تحديد التنسيقات الافتراضية للموقع',[[ 'Theme style provides shared presentation for headings, buttons, links and forms. Site layout defines content width and default container gaps. Check these defaults before compensating with many element-level adjustments.','تحدد Theme style مظهرًا مشتركًا للعناوين والأزرار والروابط والنماذج، وتضبط إعدادات Layout عرض المحتوى والمسافات الافتراضية للحاويات. راجع هذه القيم قبل إضافة تعديلات كثيرة لكل عنصر.']])
],['fonts-icons','components','responsive']),
guide('saving','start','Save, publish & restore','الحفظ والنشر واستعادة النسخ','Understand Undo, History, saved revisions and deactivation.','الفرق بين التراجع وسجل التعديلات والمراجعات المحفوظة وتعطيل الإضافة.',[
 section('save','Confirm that your work is saved','التأكد من حفظ عملك',[[ 'Use Save, or Ctrl+S / Command+S, and wait for the status to confirm success. Choose the intended draft or publishing state. A save error is not confirmation that the latest work reached the server.','استخدم Save أو Ctrl+S / Command+S، وانتظر تأكيد نجاح الحفظ. اختر حالة المسودة أو النشر المطلوبة. ظهور خطأ في الحفظ لا يعني وصول آخر تعديلاتك إلى الخادم.']]),
 section('restore','Choose the right recovery tool','اختيار وسيلة الاستعادة المناسبة',[[ 'Undo and Redo navigate editing changes, and History helps you inspect those steps. Saved Revisions are persisted versions of the page that you can return to later. They serve a different purpose from an in-session undo stack.','تتنقل Undo وRedo بين تعديلات التحرير، وتعرض History هذه الخطوات. أما Revisions فهي نسخ محفوظة من الصفحة يمكنك الرجوع إليها لاحقًا، وتختلف عن سجل التراجع داخل جلسة التحرير.']], [['Before restoring a revision, save any current work you want to keep.','قبل استعادة مراجعة، احفظ العمل الحالي الذي تريد الاحتفاظ به.'],['Open Revisions, inspect the available version and restore the intended one. Recheck the page and save the restored design when required.','افتح Revisions، وراجع النسخة المطلوبة ثم استعدها. افحص الصفحة واحفظ التصميم المستعاد عند الحاجة.']]),
 section('deactivate','What deactivation does','ماذا يحدث عند تعطيل الإضافة؟',[[ 'Deactivating Zadex stops rendering its layouts but retains saved designs. The page shows its normal WordPress content, which can be empty. Reactivating Zadex makes its saved designs render again.','يوقف تعطيل Zadex عرض تخطيطاته، مع الاحتفاظ بالتصاميم المحفوظة. تعرض الصفحة محتواها المعتاد في WordPress، وقد يكون فارغًا. تظهر التصاميم المحفوظة مجددًا عند إعادة تفعيل الإضافة.']])
],['import-export','troubleshooting']),
guide('theme-builder','site','Theme Builder','منشئ القوالب','Design headers, footers, content templates and their display rules.','تصميم الترويسات والتذييلات وقوالب المحتوى وتحديد أماكن عرضها.',[
 section('types','Choose a template type','اختيار نوع القالب',[[ 'Theme Builder supports header, footer, single, archive, search, 404, loop-item and popup templates. WooCommerce adds product and shop templates when it is active. Theme parts are different from a normal page design.','يدعم Theme Builder قوالب الترويسة والتذييل والمحتوى المفرد والأرشيف والبحث والخطأ 404 وعنصر حلقة المحتوى والنافذة المنبثقة. يضيف WooCommerce قوالب المنتج والمتجر عند تفعيله. تختلف أجزاء القالب عن تصميم صفحة عادية.']]),
 section('create','Create and assign a template','إنشاء القالب وتحديد ظهوره',[],[['Open Zadex → Theme Builder in the dashboard and create the template type you need.','افتح Zadex ← Theme Builder من لوحة التحكم، وأنشئ النوع المطلوب.'],['Design it in the editor. In a single-content template, use dynamic elements such as Post title and Post content so each post supplies its own data.','صمّمه داخل المحرر. في قالب المحتوى المفرد استخدم عناصر ديناميكية مثل Post title وPost content ليعرض كل منشور بياناته الخاصة.'],['Set display conditions for the whole site or specific pages, content types, taxonomies or archives. Use exclusions where needed.','اضبط شروط العرض للموقع بالكامل أو لصفحات وأنواع محتوى وتصنيفات وأرشيفات محددة، وأضف استثناءات عند الحاجة.'],['Save the template, then test a URL that should match and a URL that should not. Avoid assigning competing templates to the same destination unintentionally.','احفظ القالب، ثم اختبر رابطًا يُفترض أن يطابق الشروط وآخر لا يطابقها. تجنب إسناد قوالب متنافسة إلى الوجهة نفسها دون قصد.']]),
 section('compatibility','Theme compatibility','التوافق مع قوالب WordPress',[[ 'Zadex supports classic and block themes, including theme-part replacement. Canvas and Full Width page templates are available for page layouts. Transparent and sticky headers have additional behavior settings.','يدعم Zadex القوالب التقليدية وقوالب المكوّنات، بما في ذلك استبدال أجزاء القالب. يتوفر Canvas وFull Width لتخطيط الصفحات، وللترويسات الشفافة والثابتة إعدادات سلوك إضافية.']])
],['dynamic-content','loops','conditions']),
guide('conditions','site','Display conditions','شروط العرض','Show an element or template only in the intended context.','عرض عنصر أو قالب في السياق الذي تحدده فقط.',[
 section('scope','Element rules and template rules','قواعد العناصر وقواعد القوالب',[[ 'Element display conditions control the visibility of an individual element. Theme Builder display rules choose where a template is applied. A popup also has targeting and frequency rules; changing one kind of rule does not replace the others.','تتحكم شروط العنصر في ظهوره، بينما تحدد قواعد Theme Builder مواضع تطبيق القالب. وللنوافذ المنبثقة قواعد استهداف وتكرار منفصلة؛ تعديل أحد هذه الأنواع لا يغني عن البقية.']]),
 section('configure','Build and test a rule','إنشاء شرط واختباره',[],[['Select the element and open Advanced → Display conditions, or open the template’s display rules in Theme Builder.','حدّد العنصر وافتح Advanced ← Display conditions، أو افتح قواعد عرض القالب في Theme Builder.'],['Choose the supported rule: user role, login state, date and time, page context, URL value or dynamic field, as appropriate.','اختر الشرط المدعوم المناسب: دور المستخدم أو حالة تسجيل الدخول أو التاريخ والوقت أو سياق الصفحة أو قيمة في الرابط أو حقل ديناميكي.'],['Choose the comparison and value offered for that rule. Review whether your conditions must match together or in an alternative group where the interface provides that choice.','حدّد المقارنة والقيمة اللتين يوفرهما الشرط. راجع ما إذا كانت الشروط مطلوبة معًا أو ضمن مجموعة بديلة حيث يتيح المحرر هذا الاختيار.'],['Test with both matching and non-matching contexts, including a logged-out browser where relevant.','اختبر حالة مطابقة وأخرى غير مطابقة، واستخدم متصفحًا غير مسجل الدخول عند الحاجة.']],['Display visibility is a presentation feature. Do not use it as a replacement for access control over private WordPress content.','شروط الظهور أداة للتحكم في العرض، وليست بديلًا عن صلاحيات الوصول إلى المحتوى الخاص داخل WordPress.'])
],['theme-builder','popups','roles']),
guide('motion','design','Motion, interactions & sticky elements','الحركة والتفاعلات والعناصر الثابتة','Choose the right kind of animation for the behavior you need.','اختيار نوع الحركة المناسب للسلوك المطلوب.',[
 section('types','Four different motion tools','أدوات الحركة المختلفة',[[ 'Entrance Motion animates an element when it appears. Motion effects provide scroll and mouse effects such as parallax, opacity, blur, rotation, scale and 3D tilt. Scroll animation links keyframes to page scrolling. Interactions use triggers and timelines to coordinate actions.','تُحرّك Entrance Motion العنصر عند ظهوره. وتوفر Motion effects تأثيرات التمرير والفأرة مثل المنظور والشفافية والتمويه والدوران والتكبير والميل ثلاثي الأبعاد. تربط Scroll animation إطارات الحركة بالتمرير، وتربط Interactions الأحداث بجداول زمنية للإجراءات.']]),
 section('timeline','Create an interaction','إنشاء تفاعل',[],[['Select the element and open its Interactions controls in Advanced.','حدّد العنصر وافتح Interactions في Advanced.'],['Choose a trigger such as page load, element visibility, hover or click. Add the supported timeline actions and configure their timing.','اختر حدثًا مثل تحميل الصفحة أو ظهور العنصر أو مرور الفأرة أو الضغط، ثم أضف إجراءات الجدول الزمني المدعومة واضبط توقيتها.'],['Use supported actions such as animation, class changes, showing or hiding an element, or opening a popup. Preview the complete sequence.','استخدم الإجراءات المدعومة مثل الحركة أو تغيير الفئات أو إظهار عنصر وإخفائه أو فتح نافذة منبثقة، ثم عاين التسلسل كاملًا.']]),
 section('sticky','Keep an element visible','تثبيت عنصر أثناء التمرير',[[ 'Sticky keeps an element at the top or bottom while scrolling, and can apply appearance changes after a scroll threshold. Check the containing layout and preview the result on mobile so the sticky element does not cover essential content.','تُبقي Sticky العنصر أعلى الشاشة أو أسفلها أثناء التمرير، ويمكن تغيير مظهره بعد حد معين. راجع الحاوية وعاين الموبايل حتى لا يغطي العنصر محتوى أساسيًا.']])
],['element-settings','popups','responsive']),
guide('dynamic-content','content','Dynamic content','المحتوى الديناميكي','Connect an element to WordPress data instead of repeating static text.','ربط العناصر ببيانات WordPress بدلًا من تكرار النصوص الثابتة.',[
 section('sources','Available data sources','مصادر البيانات',[[ 'Sources include post title, excerpt, content, date, author, permalink, taxonomies, featured image and comment count; site name, logo, URL and description; user and archive data; current date; URL values; and custom fields.','تشمل المصادر عنوان المقالة ومقتطفها ومحتواها وتاريخها وكاتبها ورابطها وتصنيفاتها وصورتها البارزة وعدد تعليقاتها، واسم الموقع وشعاره ورابطه ووصفه، وبيانات المستخدم والأرشيف والتاريخ الحالي وقيم الرابط والحقول المخصصة.'],['Integrations with ACF, Pods, Toolset and Meta Box are available when the corresponding plugin is installed. A dynamic control must support the value type you want to bind, such as text, image, URL, number or color.','تتوفر تكاملات ACF وPods وToolset وMeta Box عند تثبيت الإضافة المقابلة. يجب أن يدعم الإعداد نوع القيمة المراد ربطها، مثل نص أو صورة أو رابط أو رقم أو لون.']]),
 section('bind','Bind and preview a field','ربط حقل ومعاينته',[],[['Select an element and find a control with dynamic-data support. Choose the dynamic source.','حدّد عنصرًا وابحث عن إعداد يدعم البيانات الديناميكية، ثم اختر المصدر.'],['Select the field or property, and provide any required custom-field key. Configure supported fallback or formatting options where offered.','اختر الحقل أو الخاصية وأدخل مفتاح الحقل المخصص عند الحاجة. اضبط خيارات التنسيق أو القيمة البديلة إذا كانت متاحة.'],['Preview with a content item that actually has that data. Also check an item with an empty field so your layout handles missing content.','عاين باستخدام عنصر محتوى يحتوي على البيانات، ثم اختبر عنصرًا بحقل فارغ للتأكد من أن التخطيط يتعامل مع غيابها.']])
],['loops','theme-builder','elements']),
guide('loops','content','Loop Builder & filtering','حلقات المحتوى والفلترة','Design one item, then display real posts or products in a repeatable layout.','تصميم عنصر واحد ثم تكراره لعرض المقالات أو المنتجات الفعلية.',[
 section('item','Design a loop item','تصميم عنصر حلقة المحتوى',[],[['Create a Loop item template in Theme Builder.','أنشئ قالب Loop item في Theme Builder.'],['Build the item with dynamic fields such as title, featured image, excerpt and permalink. Avoid typing the same fixed article title into the template.','صمّم العنصر باستخدام حقول ديناميكية مثل العنوان والصورة البارزة والمقتطف والرابط. لا تكتب عنوان مقالة ثابتًا داخل القالب الذي سيُكرّر.'],['Save the template, insert Loop Grid or Loop Carousel into a page, and choose the loop item.','احفظ القالب، وأدرج Loop Grid أو Loop Carousel في الصفحة ثم اختر قالب العنصر.']]),
 section('query','Choose and navigate content','اختيار المحتوى والتنقل بين نتائجه',[[ 'Configure the query for the intended content type and taxonomy restrictions. Set ordering and the number of items. Depending on the element, pagination, Load more or infinite loading are available.','اضبط الاستعلام على نوع المحتوى والتصنيفات المطلوبة، وحدّد الترتيب وعدد العناصر. تتوفر حسب العنصر خيارات ترقيم الصفحات أو Load more أو التحميل المستمر.'],['Taxonomy Filter provides visitor-driven filtering without a full-page reload. Connect it to the appropriate loop using its controls, then test every filter and the unfiltered state. Alternate loop templates can style designated positions, such as every third item, differently.','تتيح Taxonomy Filter للزائر فلترة النتائج دون إعادة تحميل الصفحة كاملة. اربطها بالحلقة المناسبة من إعداداتها ثم اختبر كل فلتر وحالة عرض الكل. ويمكن استخدام قوالب بديلة لتنسيق مواضع معينة، مثل كل عنصر ثالث.']]),
 section('empty','Check empty and long content','اختبار النتائج الفارغة والمحتوى الطويل',[[ 'Test an empty query, a long title and a missing featured image. If no items appear, verify the content type, published content, filters and dynamic preview context before changing the design.','اختبر استعلامًا بلا نتائج وعنوانًا طويلًا ومحتوى دون صورة بارزة. إذا لم تظهر عناصر، راجع نوع المحتوى ووجود محتوى منشور والفلاتر وسياق المعاينة الديناميكية قبل تعديل التصميم.']])
],['dynamic-content','theme-builder','woocommerce']),
guide('popups','site','Build and trigger a popup','إنشاء نافذة منبثقة وتشغيلها','Separate popup design, triggering, targeting and frequency.','الفصل بين تصميم النافذة وأحداث تشغيلها واستهدافها وتكرار ظهورها.',[
 section('design','Design the popup','تصميم النافذة',[],[['Create a Popup template and edit its content. Choose a centered, side, fullscreen, top-bar or bottom-bar layout.','أنشئ قالب Popup وعدّل محتواه. اختر تخطيطًا وسط الشاشة أو جانبيًا أو بملء الشاشة أو شريطًا أعلى الصفحة أو أسفلها.'],['Configure dimensions, overlay, close button, entry and exit motion, scrolling behavior and automatic closing where needed.','اضبط الأبعاد والخلفية المعتمة وزر الإغلاق وحركتي الدخول والخروج وسلوك تمرير الصفحة والإغلاق التلقائي عند الحاجة.']]),
 section('trigger','Choose when it opens','تحديد وقت الفتح',[[ 'Available triggers include a time delay, scroll progress or an element reached, click, inactivity, exit intent and ad-block detection. Popups can also be opened by supported button actions, form actions or a countdown end action.','تشمل أحداث التشغيل التأخير الزمني ونسبة التمرير أو الوصول إلى عنصر والضغط والخمول ونية مغادرة الصفحة واكتشاف مانع الإعلانات. ويمكن فتح النافذة أيضًا بإجراءات الأزرار أو النماذج أو انتهاء العد التنازلي.']]),
 section('targeting','Set audience and frequency','ضبط الجمهور والتكرار',[[ 'Review page or visit thresholds, referral source, login state, device restrictions, maximum impressions and the wait after dismissal. A popup can be correctly designed but intentionally suppressed by one of these rules.','راجع شروط عدد الصفحات أو الزيارات ومصدر الإحالة وتسجيل الدخول والأجهزة والحد الأقصى للظهور والانتظار بعد الإغلاق. قد يكون التصميم صحيحًا لكن تمنع إحدى هذه القواعد ظهوره عن قصد.']], [['Save the popup and its rules. Test a qualifying visit, close the popup and check that dismissal behavior follows your configuration.','احفظ النافذة وقواعدها. اختبر زيارة مستوفية للشروط، ثم أغلق النافذة وتأكد من اتباع إعدادات الإغلاق والتكرار.'],['Check mobile placement and make sure the close control remains reachable.','راجع موضع النافذة على الموبايل وتأكد من إمكانية الوصول إلى زر الإغلاق.']])
],['conditions','forms','motion']),
guide('forms','forms','Create a form','إنشاء نموذج','Fields, multi-step validation, submission actions and the inbox.','الحقول والتحقق في النماذج متعددة الخطوات والإجراءات وصندوق الردود.',[
 section('fields','Build the field list','إنشاء قائمة الحقول',[],[['Insert the full Form element for field-level control, or Contact Form for a simpler contact form.','أدرج عنصر Form الكامل للتحكم في الحقول، أو Contact Form لنموذج تواصل أبسط.'],['Add fields, assign meaningful IDs and labels, and choose their types and required status. Supported types include text, textarea, email, phone, number, date, time, select, radio, checkbox, acceptance, upload, password, hidden and HTML information.','أضف الحقول وحدّد معرّفات وتسميات واضحة وأنواعها وحالة الإلزام. تشمل الأنواع النص والنص متعدد الأسطر والبريد والهاتف والرقم والتاريخ والوقت والقائمة والاختيار الواحد والمتعدد والموافقة والرفع وكلمة المرور والحقل المخفي والمحتوى التوضيحي HTML.'],['Set upload restrictions through the provided controls where applicable. Do not request information you do not need.','اضبط قيود رفع الملفات من الأدوات المتاحة حيث تنطبق، ولا تطلب بيانات لا تحتاجها.']]),
 section('steps','Use multiple steps','تقسيم النموذج إلى خطوات',[[ 'Configure the step structure, progress display and navigation buttons. Each step validates before progression, and the server also validates submissions. Test missing required values and invalid email input, not only the happy path.','اضبط هيكل الخطوات وعرض التقدم وأزرار التنقل. تتحقق كل خطوة قبل الانتقال، ويتحقق الخادم أيضًا من الردود. اختبر الحقول المطلوبة الفارغة والبريد غير الصحيح، ولا تكتفِ بتجربة الإرسال الناجحة.']]),
 section('actions','Configure what happens after submit','ضبط ما يحدث بعد الإرسال',[[ 'Choose the actions you need: Email, Email 2, redirect, popup, webhook or a supported service integration. Configure each selected action; simply selecting an action does not complete its destination settings.','اختر الإجراءات المطلوبة: Email أو Email 2 أو التحويل أو نافذة منبثقة أو webhook أو خدمة مدعومة. أكمل إعداد كل إجراء؛ اختياره وحده لا يحدد وجهته.'],['Use field shortcodes in supported settings to insert submitted values. For example, a field with ID email can be referenced as shown below.','استخدم الرموز المختصرة للحقول في الإعدادات الداعمة لإدراج القيم المُرسلة. مثلًا، يمكن الإشارة إلى حقل معرّفه email كما يلي.']],[],null,'[field:email]'),
 section('inbox','Review received messages','مراجعة الردود المستلمة',[[ 'Open Zadex → Submissions to review stored messages. Mark messages read or unread, delete them when appropriate, or export CSV. Confirm the actual inbox and email delivery with a controlled test before relying on a live form.','افتح Zadex ← Submissions لمراجعة الردود المحفوظة. علّم الرسائل كمقروءة أو غير مقروءة، واحذفها عند الحاجة أو صدّرها بصيغة CSV. اختبر وصول الرد لصندوقه ووصول البريد فعليًا قبل الاعتماد على النموذج.']])
],['form-integrations','spam','troubleshooting']),
guide('form-integrations','forms','Email, webhooks & integrations','البريد وWebhooks والتكاملات','Connect a form action to the right destination and verify delivery.','ربط إجراء النموذج بالوجهة الصحيحة والتحقق من وصوله.',[
 section('email','Email and Email 2','البريد الأول والثاني',[[ 'Set recipients, subject and message in the selected email action. Email 2 is a separate action, useful for a different recipient or a visitor response. Review the configured sender and reply-to values and test delivery through your WordPress mail setup.','حدّد المستلمين والعنوان والمحتوى داخل إجراء البريد. Email 2 إجراء مستقل يمكن استخدامه لمستلم مختلف أو للرد على الزائر. راجع عنوان المرسل والرد واختبر التسليم من خلال إعداد البريد في WordPress.']]),
 section('services','Connect a supported service','ربط خدمة مدعومة',[],[['Open the Zadex dashboard settings and configure the credentials required by your chosen email service. Keep secret credentials in the provided settings, not in public page text.','افتح إعدادات Zadex وأدخل بيانات الاتصال المطلوبة لخدمة البريد المختارة. استخدم الحقول المخصصة للمفاتيح السرية، ولا تضعها في نص ظاهر للزوار.'],['In the Form element, add the service action and select its destination list or audience and field mapping where provided.','داخل عنصر Form، أضف إجراء الخدمة وحدّد القائمة أو الجمهور وربط الحقول حسب الخيارات المتاحة.'],['Supported services include Mailchimp, ActiveCampaign, GetResponse, Kit / ConvertKit, MailerLite and Drip. Slack and Discord notification actions use their configured destinations.','تشمل الخدمات المدعومة Mailchimp وActiveCampaign وGetResponse وKit / ConvertKit وMailerLite وDrip. وتستخدم إشعارات Slack وDiscord الوجهات المحددة في إعداداتها.'],['Send a controlled test and inspect the receiving service. A success message on the page alone does not prove every external action reached its destination.','أرسل اختبارًا محدودًا وراجع الخدمة المستقبِلة. رسالة النجاح على الصفحة وحدها لا تثبت وصول جميع الإجراءات الخارجية إلى وجهاتها.']]),
 section('webhooks','Webhooks and retries','Webhooks وإعادة المحاولة',[[ 'Use a webhook action for a receiving endpoint such as an automation in Zapier, Make or n8n. Configure the URL and the action’s supported payload settings. The plugin provides automatic retries for failed webhook deliveries.','استخدم إجراء webhook لعنوان استقبال مثل أتمتة في Zapier أو Make أو n8n. حدّد الرابط وإعدادات البيانات التي يتيحها الإجراء. توفر الإضافة إعادة محاولة تلقائية عند فشل تسليم webhook.'],['Treat an endpoint as an external destination: review the fields you send and confirm the receiver accepts the expected data.','تعامل مع العنوان كوجهة خارجية: راجع الحقول المُرسلة وتأكد من قبول المستقبِل للبيانات المتوقعة.']])
],['forms','spam','privacy']),
guide('spam','forms','Protect forms from spam','حماية النماذج من الرسائل المزعجة','Use built-in checks and configure optional reCAPTCHA correctly.','استخدام الحماية المدمجة وإعداد reCAPTCHA الاختياري.',[
 section('builtin','Built-in form protection','الحماية المدمجة',[[ 'The form system provides a honeypot and submission rate limiting, with validation in the browser and on the server. Configure spam settings on the form and test a normal submission after changing them.','يوفر نظام النماذج حقلًا خفيًا لاصطياد الروبوتات وحدودًا لمعدل الإرسال، مع التحقق في المتصفح والخادم. اضبط حماية النموذج واختبر إرسالًا طبيعيًا بعد تغييرها.']]),
 section('recaptcha','Configure reCAPTCHA','إعداد reCAPTCHA',[],[['Obtain the matching reCAPTCHA v2 or v3 credentials for your site from the service.','جهّز بيانات reCAPTCHA v2 أو v3 المطابقة لموقعك من الخدمة.'],['In the Zadex dashboard settings, enter the Site key and Secret key. Save the settings.','أدخل Site key وSecret key في إعدادات Zadex بلوحة التحكم، ثم احفظ.'],['Enable the corresponding reCAPTCHA mode in the form. Ensure the mode and domain match your service configuration, then test the public page.','فعّل وضع reCAPTCHA المقابل داخل النموذج. تأكد من تطابق الوضع والنطاق مع إعداد الخدمة، ثم اختبر الصفحة العامة.']],['reCAPTCHA is an optional external service. Its use can introduce external requests and should be reflected in your own site disclosures.','reCAPTCHA خدمة خارجية اختيارية. قد يؤدي استخدامها إلى طلبات خارجية ويجب مراعاتها في إفصاحات موقعك.'])
],['forms','form-integrations','privacy']),
guide('components','content','Templates & connected components','القوالب والمكونات المترابطة','Choose between reusable content, linked components and global widgets.','الاختيار بين المحتوى المحفوظ والمكونات المرتبطة والعناصر العامة.',[
 section('library','Start with saved content','البدء بمحتوى محفوظ',[[ 'The library includes starter sections for common page structures and a complete Link in bio page. You can also save a section or page as a template and insert it later. Review inserted sample content before publishing it.','تضم المكتبة أقسامًا جاهزة للتخطيطات الشائعة وصفحة Link in bio كاملة. ويمكن حفظ قسم أو صفحة كقالب لإدراجه لاحقًا. راجع المحتوى التجريبي الذي أدرجته قبل النشر.']]),
 section('linked','Create a linked component','إنشاء مكوّن مرتبط',[],[['Select the part of the design you want to share and use Save as component.','حدّد الجزء الذي تريد مشاركته واستخدم Save as component.'],['Insert the component in the pages that need it. Manage components from Zadex → Components and inspect where they are used.','أدرج المكوّن في الصفحات المطلوبة، وأدر المكونات من Zadex ← Components مع مراجعة مواضع استخدامها.'],['Edit the shared component to update connected instances. Use supported instance overrides when a particular copy needs different content while keeping the rest linked.','عدّل المكوّن المشترك لتحديث نسخه المرتبطة. استخدم التخصيصات المدعومة للنسخة عندما تحتاج محتوى مختلفًا مع استمرار ارتباط بقية الإعدادات.']]),
 section('global','Global widgets and shared styles','العناصر العامة والتنسيقات المشتركة',[[ 'A global widget applies the connected idea to one element. Global classes share styles rather than an entire content structure. Choose a component for repeated content structure, and a class for repeated styling.','يطبّق العنصر العام فكرة الارتباط على عنصر واحد. أما الفئة العامة فتشارك التنسيق دون هيكل المحتوى بالكامل. استخدم المكوّن لتكرار البنية والمحتوى، والفئة لتكرار التنسيق.']])
],['global-styles','import-export','elements']),
guide('import-export','content','Import & export','الاستيراد والتصدير','Move a page as JSON or transfer a complete site kit.','نقل صفحة بصيغة JSON أو نقل حزمة موقع متكاملة.',[
 section('page','Transfer a page','نقل صفحة',[],[['Save the page you want to transfer and use the page export capability to download its JSON.','احفظ الصفحة المطلوبة، ثم استخدم تصدير الصفحة لتنزيل ملف JSON الخاص بها.'],['On the destination installation, use the page import capability with a valid Zadex page JSON. Inspect the imported structure before publishing.','في الموقع المستقبِل، استخدم استيراد الصفحة مع ملف JSON صالح من Zadex. راجع الهيكل المستورد قبل النشر.']],['A website playground sample JSON is a demonstration file, not a real Zadex page export.','ملف JSON الذي تنزّله من مساحة التجربة في هذا الموقع ملف توضيحي، وليس تصدير صفحة فعليًا من Zadex.']),
 section('kit','Move a site kit','نقل حزمة موقع',[],[['Open Zadex → Import / Export and export the site kit ZIP. Kits include pages, theme templates, global settings and images.','افتح Zadex ← Import / Export وصدّر حزمة الموقع ZIP. تتضمن الحزمة الصفحات وقوالب الموقع والإعدادات العامة والصور.'],['On the destination site, import the kit and review the choices offered by the importer. Links are adjusted for the destination.','استورد الحزمة في الموقع الجديد وراجع الخيارات التي يعرضها المستورد. تُضبط الروابط بما يناسب الموقع المستقبِل.'],['Check media, page URLs, menus, template rules and global styles after import. Reconfigure external services for the destination as needed.','راجع الوسائط وروابط الصفحات والقوائم وشروط القوالب والتنسيقات العامة بعد الاستيراد. أعد إعداد الخدمات الخارجية للموقع الجديد عند الحاجة.']],['A kit is not a full hosting backup. Keep an independent site backup before an import that could change existing content or settings.','الحزمة ليست نسخة احتياطية كاملة للاستضافة. احتفظ بنسخة مستقلة قبل استيراد قد يغيّر محتوى أو إعدادات موجودة.'])
],['components','saving','theme-builder']),
guide('fonts-icons','design','Fonts & icons','الخطوط والأيقونات','Upload brand assets and use them from the editor.','رفع أصول هويتك واستخدامها داخل المحرر.',[
 section('fonts','Add a custom font','إضافة خط مخصص',[],[['Open Zadex → Custom Fonts. Add the family and upload its available WOFF2, WOFF or TTF files.','افتح Zadex ← Custom Fonts. أضف عائلة الخط وارفع ملفات WOFF2 أو WOFF أو TTF المتاحة.'],['Assign the correct weight and style to each variation so regular, bold and italic do not point to the wrong file.','حدّد الوزن والنمط الصحيحين لكل نسخة حتى لا تستخدم العادي أو العريض أو المائل ملفًا غير مناسب.'],['Save, then select the font in the editor or assign it through Global fonts. Check that the actual font includes the scripts your site uses.','احفظ الخط ثم اختره في المحرر أو عيّنه عبر Global fonts. تأكد من احتواء الخط على حروف اللغات المستخدمة في موقعك.']]),
 section('adobe','Adobe Fonts','Adobe Fonts',[[ 'Connect an Adobe Fonts project ID from Custom Fonts when you choose to use that service. This differs from locally uploaded font files and depends on the external project being available.','يمكن ربط رقم مشروع Adobe Fonts من Custom Fonts إذا اخترت هذه الخدمة. يختلف ذلك عن ملفات الخطوط المرفوعة محليًا ويعتمد على إتاحة المشروع الخارجي.']]),
 section('icons','Use or upload an icon set','استخدام مجموعة أيقونات أو رفعها',[[ 'Font Awesome Free icons are bundled. For a custom set, open Zadex → Custom Icons and upload a supported collection from Fontello, IcoMoon or Fontastic, then choose it from compatible icon controls.','أيقونات Font Awesome Free مضمّنة في الإضافة. لرفع مجموعة مخصصة، افتح Zadex ← Custom Icons وارفع مجموعة مدعومة من Fontello أو IcoMoon أو Fontastic، ثم اخترها من أدوات الأيقونات الداعمة.']])
],['global-styles','arabic','elements']),
guide('roles','site','Team, permissions & notes','الفريق والصلاحيات والملاحظات','Give teammates the editing scope they need and keep feedback on the design.','تحديد صلاحيات الفريق وإضافة الملاحظات داخل التصميم.',[
 section('access','Choose an access mode','اختيار مستوى الصلاحية',[[ 'Role Manager supports No access, Content only and Full access for WordPress roles. Content-only editing permits supported text, image and link changes without opening design and structure controls. Restrictions are also checked on the server.','يدعم Role Manager مستويات No access وContent only وFull access لأدوار WordPress. يسمح مستوى المحتوى فقط بتعديل النصوص والصور والروابط المدعومة دون إتاحة التصميم والبنية. وتُراجع القيود على الخادم أيضًا.']], [['Open Zadex → Role Manager with an account allowed to manage these settings.','افتح Zadex ← Role Manager بحساب مسموح له بإدارة هذه الإعدادات.'],['Assign the intended mode to each role. Test using an account with that role rather than relying on what an administrator sees.','عيّن المستوى المطلوب لكل دور، واختبر بحساب يحمل ذلك الدور بدلًا من الاعتماد على واجهة مدير الموقع.']]),
 section('locks','Lock an element','قفل عنصر',[[ 'Element locks help protect selected design areas. A locked element or restricted role can make an editor action unavailable even though that capability exists in Zadex. Check both before treating a disabled control as a defect.','تساعد أقفال العناصر على حماية أجزاء من التصميم. قد يمنع القفل أو الدور المقيّد إجراءً معينًا رغم توفره في Zadex. راجع الأمرين قبل اعتبار الإعداد المعطّل مشكلة.']]),
 section('notes','Discuss work in context','مناقشة العمل في موضعه',[[ 'Attach a note to an element, add replies and use @mentions to notify teammates by email. Resolve a completed thread or reopen it if work continues. A note is review feedback, not a change to the page’s visitor-facing content.','ثبّت ملاحظة على عنصر وأضف ردودًا واستخدم @mentions لإشعار الزملاء بالبريد. أغلق النقاش بعد إنجازه أو أعد فتحه عند استئناف العمل. الملاحظة تعليق للمراجعة وليست تعديلًا على المحتوى الظاهر للزوار.']])
],['editor-access','components','saving']),
guide('woocommerce','shop','Design a WooCommerce store','تصميم متجر WooCommerce','Product templates, shopping pages and the 18 conditional store elements.','قوالب المنتجات وصفحات التسوق وعناصر المتجر الثمانية عشر.',[
 section('enable','Enable the store context','تفعيل سياق المتجر',[[ 'WooCommerce must be installed and active for its Zadex elements and template types to appear. Create and configure products in WooCommerce; a page-builder product element displays that data rather than replacing product management.','يجب تثبيت WooCommerce وتفعيله لإظهار عناصره وأنواع قوالبه في Zadex. أنشئ المنتجات واضبطها داخل WooCommerce؛ تعرض عناصر المنشئ هذه البيانات ولا تستبدل إدارة المنتجات.']]),
 section('product','Build a product template','إنشاء قالب منتج',[],[['In Theme Builder, create a product template. Add Product Title, Product Images, Product Price, stock, rating, metadata and Add To Cart as needed.','أنشئ قالب منتج في Theme Builder، وأضف Product Title وProduct Images وProduct Price والمخزون والتقييم والبيانات وزر Add To Cart حسب حاجتك.'],['Use Product Data Tabs, Related Products or Upsells to extend the page, and set template display conditions for the intended products.','أضف Product Data Tabs أو Related Products أو Upsells لتكملة الصفحة، واضبط شروط القالب للمنتجات المطلوبة.'],['Preview products with different prices, stock states and image collections.','عاين منتجات بأسعار وحالات مخزون وصور مختلفة.']]),
 section('journey','Complete the shopping journey','استكمال رحلة الشراء',[[ 'Available elements include Products, Product Categories, Cart, Checkout, My Account, Menu Cart and Purchase Summary. Review links between the shop, product, cart and checkout pages on a configured WooCommerce installation.','تشمل العناصر Products وProduct Categories وCart وCheckout وMy Account وMenu Cart وPurchase Summary. راجع الربط بين المتجر والمنتج والسلة وإتمام الشراء داخل موقع WooCommerce مُعدّ فعليًا.'],['The website’s store simulations do not create orders or process payments. Test your actual WooCommerce configuration separately before accepting customers.','محاكاة المتجر في هذا الموقع لا تنشئ طلبات ولا تعالج مدفوعات. اختبر إعداد WooCommerce الفعلي بشكل مستقل قبل استقبال العملاء.']])
],['payments','theme-builder','loops']),
guide('payments','shop','PayPal & Stripe buttons','أزرار PayPal وStripe','Configure a real payment destination rather than treating a preview as a transaction.','إعداد وجهة دفع فعلية وفهم الفرق بينها وبين المعاينة.',[
 section('paypal','PayPal button','زر PayPal',[[ 'Add the PayPal button element and configure the account or destination and the supported action, amount and currency controls shown in its reference. The button relies on the PayPal service and the account configuration.','أضف عنصر PayPal button واضبط الحساب أو الوجهة والإجراء والمبلغ والعملة حسب أدواته في المرجع. يعتمد الزر على خدمة PayPal وإعداد حسابها.']]),
 section('stripe','Stripe button','زر Stripe',[[ 'Stripe supports a payment-link destination and a server-created Checkout flow. For Checkout mode, configure the Stripe secret key in Zadex dashboard payment settings; the key remains server-side. Set the button’s supported amount, currency and destination options.','يدعم Stripe وجهة Payment Link وتدفق Checkout ينشئه الخادم. لاستخدام Checkout، أضف Stripe secret key في إعدادات الدفع بلوحة Zadex؛ يبقى المفتاح على الخادم. اضبط المبلغ والعملة والوجهة من الخيارات المدعومة للزر.'],['Do not place a secret key in a link, custom attribute or page text. Confirm account settings and use the provider’s testing facilities before enabling live payments.','لا تضع مفتاحًا سريًا في رابط أو خاصية مخصصة أو نص الصفحة. راجع إعداد الحساب واستخدم وسائل الاختبار لدى المزود قبل تفعيل الدفع الفعلي.']]),
 section('verify','Verify the complete flow','التحقق من التدفق كاملًا',[[ 'Check the selected action, currency and expected return destination. A visible button or the website’s illustrative payment preview does not prove a charge was processed. Verify transactions in the actual provider account.','راجع الإجراء والعملة ووجهة العودة. ظهور الزر أو معاينة الدفع التوضيحية في هذا الموقع لا يعني معالجة أي مبلغ. تحقق من المعاملات داخل حساب مزود الدفع الفعلي.']])
],['woocommerce','privacy','elements']),
guide('site-settings','site','Site settings & maintenance','إعدادات الموقع والصيانة','Shared layout behavior, transitions, contact buttons and maintenance pages.','سلوك التخطيط المشترك والانتقالات وأزرار التواصل وصفحات الصيانة.',[
 section('site','Site-wide behavior','السلوك العام للموقع',[[ 'Site settings include global styling, layout, breakpoints, image lightbox, page transitions and loading appearance. Floating buttons provide contact destinations such as WhatsApp, phone and email, or a return-to-top action.','تضم Site settings التنسيقات العامة والتخطيط ومقاسات الشاشات وعارض الصور وانتقالات الصفحات ومظهر التحميل. وتوفر الأزرار العائمة وجهات مثل WhatsApp والهاتف والبريد أو الرجوع إلى الأعلى.']]),
 section('maintenance','Enable a maintenance or coming-soon page','تفعيل صفحة صيانة أو قريبًا',[],[['Create the page you want visitors to see, then select it in the maintenance or coming-soon settings.','أنشئ الصفحة التي تريد عرضها للزوار، ثم اخترها في إعدادات الصيانة أو قريبًا.'],['Choose which roles are allowed to keep viewing the normal site.','حدّد الأدوار التي يُسمح لها بمشاهدة الموقع العادي.'],['Test both an allowed signed-in account and a logged-out browser. Maintenance mode returns HTTP 503 to visitors and search engines.','اختبر حسابًا مسموحًا ومتصفحًا غير مسجل الدخول. يعيد وضع الصيانة HTTP 503 للزوار ومحركات البحث.'],['Turn the mode off when the normal site should become available again.','عطّل الوضع عند الرغبة في إتاحة الموقع العادي مجددًا.']])
],['global-styles','conditions','troubleshooting']),
guide('arabic','start','Arabic, RTL & editor appearance','العربية واتجاه RTL ومظهر المحرر','Change the editor language through your WordPress user preferences.','تغيير لغة المحرر من تفضيلات حسابك في WordPress.',[
 section('language','Set the user language','تحديد لغة المستخدم',[],[['Open your WordPress user profile and choose Arabic as the user language. Save the profile.','افتح ملف حسابك في WordPress واختر العربية لغةً للمستخدم، ثم احفظ الملف.'],['Reopen the Zadex editor. Its Arabic interface and right-to-left layout follow the WordPress user language.','أعد فتح محرر Zadex. تتبع الواجهة العربية واتجاهها من اليمين إلى اليسار لغة مستخدم WordPress.']],['Changing this website’s language changes the documentation and demonstrations, not your WordPress account or plugin settings.','تغيير لغة هذا الموقع يغيّر التوثيق والعروض التوضيحية، ولا يغيّر حسابك أو إعدادات الإضافة داخل WordPress.']),
 section('content','Check the content itself','مراجعة المحتوى نفسه',[[ 'Use a font that includes Arabic characters and check mixed Arabic/Latin content, navigation, icons and device overrides. Text alignment remains a design choice; translating text does not automatically settle every layout decision.','استخدم خطًا يدعم الحروف العربية وراجع مزج العربية واللاتينية والقوائم والأيقونات وتخصيص الأجهزة. تظل المحاذاة اختيارًا تصميميًا؛ ترجمة النص وحدها لا تحسم كل تفاصيل التخطيط.']]),
 section('appearance','Light and dark editor appearance','مظهر المحرر الفاتح والداكن',[[ 'The editor offers dark mode for its interface. This changes the editing environment; design your page’s own colors through its element and site controls.','يوفر المحرر وضعًا داكنًا لواجهته. يغيّر ذلك بيئة التحرير؛ أما ألوان الصفحة نفسها فتُضبط من أدوات العناصر وإعدادات الموقع.']])
],['fonts-icons','responsive','editor']),
guide('privacy','help','Performance & external services','الأداء والخدمات الخارجية','Understand generated styles, conditional scripts and optional connections.','فهم إنشاء التنسيقات والسكربتات حسب الحاجة والاتصالات الاختيارية.',[
 section('output','How the page output is prepared','كيف يُجهّز إخراج الصفحة؟',[[ 'Zadex generates page CSS at save time and loads the generated stylesheet in the document head. Frontend scripts are loaded for features that need them, such as sliders, popups or effects. These are implementation characteristics, not a promised page-speed score.','ينشئ Zadex ملف CSS للصفحة عند الحفظ ويحمّله في رأس المستند. تُحمّل سكربتات الواجهة للمميزات التي تحتاجها مثل العوارض والنوافذ والمؤثرات. هذه خصائص للتنفيذ وليست وعدًا بدرجة محددة لسرعة الصفحة.'],['Images, the theme, hosting, other plugins and selected external services still influence the result. Check the actual public page after saving.','تظل الصور والقالب والاستضافة والإضافات الأخرى والخدمات الخارجية مؤثرة على النتيجة. راجع الصفحة العامة الفعلية بعد الحفظ.']]),
 section('services','When an external service is involved','متى تُستخدم خدمة خارجية؟',[[ 'The plugin does not send visitor tracking data to its developers. Optional services you configure can still receive data: video providers, Google Maps, SoundCloud, Facebook, Adobe Fonts, reCAPTCHA, form integrations and payment providers are examples.','لا ترسل الإضافة بيانات تتبّع الزوار إلى مطوريها. لكن الخدمات الاختيارية التي تضبطها قد تستقبل بيانات، مثل مزودي الفيديو وGoogle Maps وSoundCloud وFacebook وAdobe Fonts وreCAPTCHA وتكاملات النماذج ومزودي الدفع.'],['Choose only the services you need and reflect their actual use in your site’s privacy information. Disabling an unused integration differs from preventing an external embed already added to a page.','استخدم الخدمات التي تحتاجها فقط، ووضّح استخدامها الفعلي في معلومات الخصوصية بموقعك. تعطيل تكامل غير مستخدم يختلف عن منع تضمين خارجي أُضيف بالفعل إلى الصفحة.']])
],['form-integrations','payments','troubleshooting']),
guide('shortcuts','reference','Keyboard shortcuts','اختصارات لوحة المفاتيح','Verified editor commands, with Ctrl on Windows and Command on macOS.','أوامر المحرر الموثقة باستخدام Ctrl على Windows وCommand على macOS.',[
 section('keys','Core commands','الأوامر الأساسية',[[ 'Use Command in place of Ctrl on macOS. Shortcuts that edit the element structure generally do not run while you are typing in an input, textarea or editable text. Save and quick search are global commands.','استخدم Command بدلًا من Ctrl على macOS. لا تعمل أوامر بنية العناصر عادةً أثناء الكتابة في حقل أو نص قابل للتحرير. الحفظ والبحث السريع من الأوامر العامة.']],[],null,'Ctrl + S        Save\nCtrl + Z        Undo\nCtrl + Shift + Z / Ctrl + Y   Redo\nCtrl + D        Duplicate element\nCtrl + C / V    Copy / paste element\nCtrl + Shift + C / V   Copy / paste style\nCtrl + K        Quick search\nCtrl + I        Navigator\nCtrl + Shift + P   Preview mode\nCtrl + Shift + D   Dark mode\nDelete          Delete selected element'),
 section('limits','When a command does nothing','عندما لا يعمل الاختصار',[[ 'Select an element first for element actions. A locked element or a role without structural access can block duplicate, delete and paste. A browser or operating-system shortcut can also take precedence.','حدّد عنصرًا أولًا للأوامر الخاصة بالعناصر. قد يمنع قفل العنصر أو غياب صلاحية البنية التكرار والحذف واللصق. وقد يتدخل اختصار للمتصفح أو نظام التشغيل.']])
],['editor','roles','saving']),
guide('elements','reference','Element reference','مرجع العناصر','Browse every public element and inspect its actual controls.','تصفح كل عنصر متاح وراجع إعداداته الفعلية.',[
 section('choose','Find the right element','اختيار العنصر المناسب',[[ 'The searchable reference below is generated from the documented plugin manifests. Each element page lists its purpose, content and style controls, available options, default values and responsive or conditional behavior.','المرجع القابل للبحث أدناه مستخرج من ملفات تعريف عناصر النسخة الموثقة. تعرض صفحة كل عنصر وظيفته وإعدادات محتواه وتنسيقه وخياراته وقيمه الافتراضية ودعم التجاوب والإعدادات المشروطة.'],['Shared Advanced controls are explained separately in Style an element, Responsive design, Motion and Display conditions. WooCommerce elements appear in the editor only when WooCommerce is active.','تُشرح أدوات Advanced المشتركة بشكل مستقل في أدلة تنسيق عنصر والتصميم المتجاوب والحركة وشروط العرض. لا تظهر عناصر WooCommerce داخل المحرر إلا عند تفعيله.']])
],['element-settings','responsive','woocommerce']),
guide('editor-access','help','The editor button is missing','زر فتح المحرر غير ظاهر','Check activation, content types and permissions before troubleshooting the page.','مراجعة التفعيل وأنواع المحتوى والصلاحيات قبل تشخيص الصفحة.',[
 section('checks','Work through these checks','راجع هذه النقاط بالترتيب',[],[['Confirm Zadex is active and that WordPress and PHP meet its minimum requirements.','تأكد من تفعيل Zadex واستيفاء WordPress وPHP للحد الأدنى المطلوب.'],['In Zadex settings, check whether the post type is enabled. A custom post type may need to be enabled explicitly.','راجع تفعيل نوع المحتوى في إعدادات Zadex. قد يحتاج نوع محتوى مخصص إلى التفعيل يدويًا.'],['Confirm your WordPress account can edit that content and that Role Manager has not assigned No access to its role.','تأكد من صلاحية حسابك لتحرير ذلك المحتوى، ومن عدم تعيين No access لدوره في Role Manager.'],['Look for Edit with Zadex in the page list, WordPress editor or admin bar. Reload the dashboard after changing settings.','ابحث عن Edit with Zadex في قائمة الصفحات أو محرر WordPress أو شريط الإدارة، وأعد تحميل لوحة التحكم بعد تغيير الإعدادات.']])
],['installation','roles','troubleshooting']),
guide('troubleshooting','help','Troubleshooting checklist','دليل حل المشكلات','Diagnose common save, display, form and dynamic-content issues.','تشخيص مشكلات الحفظ والعرض والنماذج والمحتوى الديناميكي.',[
 section('save','The page did not save','الصفحة لم تُحفظ',[[ 'Read the editor’s error message and confirm your login and permission to edit the content. Check the connection and retry Save. Keep the editor open until you have confirmed the latest work is saved; do not assume an earlier status includes your newest change.','اقرأ رسالة الخطأ وتحقق من تسجيل الدخول وصلاحية تحرير المحتوى، ثم راجع الاتصال وأعد الحفظ. أبقِ المحرر مفتوحًا حتى تتأكد من حفظ آخر تعديل، ولا تفترض أن حالة سابقة تشمل التغيير الأخير.']]),
 section('display','The public page looks different','الصفحة العامة تبدو مختلفة',[[ 'Confirm the intended design was saved, then compare the same URL and device width. Check responsive overrides, element visibility, display conditions and the active Theme Builder template. If a cache layer is used, refresh its cached output through that system’s controls.','تأكد من حفظ التصميم، ثم قارن الرابط نفسه وعرض الجهاز نفسه. راجع القيم المتجاوبة وإظهار العنصر وشروط العرض وقالب Theme Builder النشط. وإذا وُجد نظام تخزين مؤقت، حدّث مخرجاته من أدواته.']]),
 section('dynamic','Dynamic content is empty','المحتوى الديناميكي فارغ',[[ 'Verify the preview content has the requested field, that the source key is correct, and that an optional custom-field plugin is active. For loops, check that published records match the query and filters. For WooCommerce, confirm the plugin is active and a product context is available.','تأكد من احتواء محتوى المعاينة على الحقل المطلوب وصحة مفتاح المصدر وتفعيل إضافة الحقول المخصصة عند استخدامها. في حلقات المحتوى راجع وجود سجلات منشورة تطابق الاستعلام والفلاتر. وفي WooCommerce راجع التفعيل وتوفر سياق منتج.']]),
 section('forms','A form action did not arrive','إجراء النموذج لم يصل',[[ 'Confirm validation succeeded, the action is selected and its destination settings are complete. Check stored submissions separately from email or service delivery. Review credentials and the receiving service, and test WordPress mail delivery for email actions.','تأكد من اجتياز التحقق واختيار الإجراء واكتمال وجهته. افحص الردود المحفوظة بشكل مستقل عن وصول البريد أو الخدمة. راجع بيانات الربط والخدمة المستقبِلة، واختبر بريد WordPress للإجراءات البريدية.']]),
 section('popup','A popup does not open','النافذة المنبثقة لا تفتح',[[ 'Check the saved popup template, trigger and target page. Review device and login restrictions, impression limits and the wait after dismissal. Test a visit that meets the configured rules.','راجع حفظ قالب النافذة وحدث التشغيل والصفحة المستهدفة، ثم قيود الجهاز وتسجيل الدخول وعدد مرات الظهور والانتظار بعد الإغلاق. اختبر زيارة تستوفي القواعد.']]),
 section('handoff','Prepare a useful issue report','تجهيز تقرير مشكلة مفيد',[[ 'Include your Zadex, WordPress and PHP versions, the relevant element or template, reproduction steps, expected and actual results, and the exact visible error. Remove secrets and personal submission data from screenshots or logs before sharing them.','اذكر إصدارات Zadex وWordPress وPHP، والعنصر أو القالب المعني، وخطوات إعادة المشكلة، والنتيجة المتوقعة والفعلية، ورسالة الخطأ كما تظهر. احذف المفاتيح السرية وبيانات الردود الشخصية من الصور والسجلات قبل مشاركتها.']])
],['editor-access','saving','forms'])
];

